// The forecast written out like a newspaper's weather column: a headline for
// the rest of the day (or for tonight and tomorrow, after five), a paragraph of
// what to expect, the week ahead beside it and the figures in small print.
import {
  kindOf, wordsFor, degrees, celsius, compass, placeClock, hourIndex, dayIndex,
  clockText, WEEKDAYS, MONTHS, temperatureColor,
} from './weather'

// The looks. "color" is the newspaper's; "high" is black on white for panels
// without color (1-bit and grey e-paper), where a grey means nothing; "inks"
// is for color e-paper, which has six solid inks and no pale shades. Without
// pale shades a day's range is a solid bar on a one-pixel track, and the
// rules between the days go.
type Theme = {
  name: 'color' | 'high' | 'inks'
  paper: string
  ink: string
  soft: string
  accent: string
  columnRule: string
  rowRule: string
  track: string
  range: (celsiusValue: number) => string
}

const THEMES: Record<string, Theme> = {
  color: {
    name: 'color', paper: '#f3eee4', ink: '#1d1a16', soft: '#6b6258', accent: '#a4461f',
    columnRule: 'border-[#1d1a16]/30', rowRule: 'border-b border-[#1d1a16]/15', track: 'bg-[#1d1a16]/10', range: temperatureColor,
  },
  high: {
    name: 'high', paper: '#ffffff', ink: '#000000', soft: '#000000', accent: '#000000',
    columnRule: 'border-[#000000]', rowRule: '', track: '', range: () => '#000000',
  },
  inks: {
    name: 'inks', paper: '#ffffff', ink: '#000000', soft: '#000000', accent: '#ff0000',
    columnRule: 'border-[#000000]', rowRule: '', track: '', range: inkFor,
  },
}

// A temperature in one of the color e-paper's inks.
function inkFor(c: number) {
  if (c < 5) return '#0000ff'
  if (c < 14) return '#00a000'
  if (c < 21) return '#ffff00'
  return '#ff0000'
}

function themeOf(app: FrameOSApp): Theme {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return THEMES.high
  if (mode === 'color') return THEMES.color
  return app.frame.paper ? THEMES.inks : THEMES.color
}

// km/h in each of Open-Meteo's wind units.
const WIND_TO_KMH: Record<string, number> = { 'km/h': 1, 'm/s': 3.6, mph: 1.609, kn: 1.852 }

function temperatureWord(c: number) {
  if (c < -8) return 'bitterly cold'
  if (c < -1) return 'freezing'
  if (c < 5) return 'cold'
  if (c < 10) return 'chilly'
  if (c < 15) return 'cool'
  if (c < 21) return 'mild'
  if (c < 26) return 'warm'
  if (c < 31) return 'hot'
  return 'sweltering'
}

// The weather now, to end "It is 4° and …".
function nowPhrase(code: number, isDay: boolean) {
  const kind = kindOf(code)
  if (kind === 'clear') return isDay ? 'sunny' : 'clear'
  if (kind === 'partly') return 'partly cloudy'
  if (kind === 'cloudy') return 'overcast'
  if (kind === 'fog') return 'foggy'
  if (kind === 'drizzle') return 'drizzling'
  if (kind === 'snow') return 'snowing'
  if (kind === 'storm') return 'thundery'
  return code >= 80 ? 'showery' : 'raining'
}

function capitalize(text: string) {
  return text.charAt(0).toUpperCase() + text.substring(1)
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const weather = app.config.weather || {}
  if (!weather.current || !weather.hourly) {
    throw new Error(weather.error || 'No weather yet')
  }
  const theme = themeOf(app)
  const PAPER = theme.paper
  const INK = theme.ink
  const SOFT = theme.soft
  const ACCENT = theme.accent
  const twelve = app.config.clock === '12h'
  const now = Date.now()
  const offset = weather.offset || 0
  const units = weather.units
  const f = weather.fahrenheit
  const hourly = weather.hourly
  const daily = weather.daily
  const local = placeClock(now, offset)
  const localHour = local.getUTCHours()
  const evening = localHour >= 17
  const first = Math.max(0, hourIndex(hourly, now))
  const today = Math.max(0, dayIndex(daily, now))
  const count = hourly.temperature.length

  // The hours the headline is about: the rest of today, or tonight and tomorrow.
  const hoursLeftToday = 24 - localHour
  const last = Math.min(count - 1, first + (evening ? hoursLeftToday + 21 : hoursLeftToday - 1))
  const hours = []
  for (let i = first; i <= last; i++) hours.push(i)
  const hourAt = (i: number) => hourly.start + i * 3600000
  const clock = (i: number) => {
    const h = placeClock(hourAt(i), offset).getUTCHours()
    if (twelve) return (h % 12 || 12) + (h < 12 ? ' am' : ' pm')
    return (h < 10 ? '0' : '') + h + ':00'
  }
  const dayOf = (i: number) => Math.floor((hourAt(i) + offset * 1000) / 86400000) - Math.floor((now + offset * 1000) / 86400000)
  const when = (i: number) => {
    const h = placeClock(hourAt(i), offset).getUTCHours()
    if (dayOf(i) <= 0) return h < 12 ? 'this morning' : h < 17 ? 'this afternoon' : h < 21 ? 'this evening' : 'tonight'
    return h < 6 ? 'overnight' : h < 12 ? 'tomorrow morning' : h < 17 ? 'tomorrow afternoon' : 'tomorrow evening'
  }
  const at = (i: number) => (dayOf(i) <= 0 && i - first < 9 ? 'around ' + clock(i) : when(i))

  // The sky.
  const lit = hours.filter((i) => hourly.isDay[i] === 1)
  const skyHours = lit.length >= 3 ? lit : hours
  let clear = 0
  let cloudy = 0
  for (const i of skyHours) {
    const kind = kindOf(hourly.code[i])
    if (kind === 'clear') clear++
    else if (kind !== 'partly') cloudy++
  }
  const daytime = lit.length >= 3
  let sky = [daytime ? 'sunny spells' : 'patchy cloud']
  if (clear >= skyHours.length * 0.6) sky = daytime ? ['bright', 'sunny'] : ['clear']
  else if (cloudy >= skyHours.length * 0.7) sky = ['grey']
  const foggyStart = hours.slice(0, 3).some((i) => kindOf(hourly.code[i]) === 'fog')

  // Rain, snow or storms: when they come, and whether they stay.
  const wet = hours.filter((i) => (hourly.precipitation[i] ?? 0) >= 0.1 || ['rain', 'drizzle', 'snow', 'storm'].includes(kindOf(hourly.code[i])))
  let precipitation = ''
  let noun = 'rain'
  if (wet.length) {
    const kinds = wet.map((i) => kindOf(hourly.code[i]))
    const codes = wet.map((i) => hourly.code[i])
    if (kinds.includes('storm')) noun = 'thunderstorms'
    else if (kinds.filter((k) => k === 'snow').length >= wet.length / 2) noun = 'snow'
    else if (codes.filter((c) => c >= 80 && c <= 82).length >= wet.length / 2) noun = 'showers'
    else if (kinds.filter((k) => k === 'drizzle').length >= wet.length / 2) noun = 'drizzle'
    let stretches = 1
    for (let k = 1; k < wet.length; k++) if (wet[k] - wet[k - 1] > 2) stretches++
    const start = wet[0]
    const end = wet[wet.length - 1]
    if (wet.length >= hours.length * 0.7) precipitation = noun + (evening ? ' through to tomorrow' : ' for most of the day')
    else if (stretches >= 3) precipitation = noun + ' on and off'
    else if (start <= first + 1) precipitation = noun + ' clearing ' + (dayOf(end + 1) <= 0 ? 'by ' + clock(end + 1) : when(end + 1))
    else precipitation = noun + ' ' + (noun === 'thunderstorms' ? 'likely ' : 'arriving ') + at(start)
  } else {
    const chance = Math.max(...hours.map((i) => hourly.rainChance[i] ?? 0))
    if (chance >= 30) precipitation = 'a chance of a shower'
  }

  // How it feels, and the wind.
  const temperatures = hours.map((i) => hourly.temperature[i])
  const highest = Math.max(...temperatures)
  const lowest = Math.min(...temperatures)
  const peak = hours[temperatures.indexOf(highest)]
  const trough = hours[temperatures.indexOf(lowest)]
  const feel = temperatureWord(celsius(daytime ? highest : (highest + lowest) / 2, f))
  const windFactor = WIND_TO_KMH[units.wind] || 1
  const strongest = Math.max(...hours.map((i) => hourly.wind[i] ?? 0))
  const windy = strongest * windFactor >= 38
  const frostHours = hours.filter((i) => dayOf(i) <= 1 && hourly.isDay[i] === 0 && celsius(hourly.temperature[i], f) < 0.5)
  const hardFrost = celsius(lowest, f) < -4

  // The headline.
  const words = sky.concat([feel], windy ? ['windy'] : [])
  const listed = words.slice(0, -1).join(', ') + ' and ' + words[words.length - 1]
  let headline = capitalize(foggyStart && sky[0] !== 'grey' ? 'foggy at first, then ' + listed : listed)
  if (precipitation) headline += ', with ' + precipitation
  if (frostHours.length && !wet.some((i) => celsius(hourly.temperature[i], f) < 1)) {
    headline += (precipitation ? '. ' : ', then ') + (precipitation ? (hardFrost ? 'A hard frost ' : 'A frost ') : hardFrost ? 'a hard frost ' : 'a frost ') + (evening ? 'overnight' : 'tonight')
  }
  headline += '.'

  // The paragraph.
  const current = weather.current
  const sentences = []
  const feelsGap = Math.abs((current.feelsLike ?? current.temperature) - current.temperature) >= (f ? 3 : 2)
  sentences.push(
    `It is ${degrees(current.temperature)} in ${weather.place || 'town'}` +
      (feelsGap ? `, though it feels like ${degrees(current.feelsLike)}` : '') +
      ` and ${nowPhrase(current.code, current.isDay)}.`,
  )
  if (!evening) {
    const tonightLow = daily.low[today + 1] ?? lowest
    sentences.push(
      highest > current.temperature + 0.5
        ? `Expect a high of ${degrees(highest)} ${at(peak)}, before it drops to ${degrees(tonightLow)} overnight.`
        : `It only gets colder from here, down to ${degrees(tonightLow)} by early tomorrow.`,
    )
  } else {
    const tomorrowHigh = daily.high[today + 1]
    const todayHigh = daily.high[today]
    const compare = tomorrowHigh - todayHigh
    const step = f ? 4 : 2
    const trend = compare >= step ? 'a warmer day' : compare <= -step ? 'a colder day' : 'much the same'
    sentences.push(`It falls to ${degrees(lowest)} ${at(trough)}; tomorrow is ${trend}, reaching ${degrees(tomorrowHigh)}.`)
  }
  const windNow = current.wind ?? 0
  const windKmh = windNow * windFactor
  const gust = current.gusts ?? 0
  const direction = ['north', 'northeast', 'east', 'southeast', 'south', 'southwest', 'west', 'northwest'][
    Math.round((((current.windDirection ?? 0) % 360) + 360) / 45) % 8
  ]
  if (windKmh < 12) sentences.push(`The wind is light, from the ${direction}.`)
  else if (windKmh < 30) sentences.push(`A ${direction}erly breeze of ${Math.round(windNow)} ${units.wind}${gust > windNow * 1.3 && gust * windFactor > 35 ? `, gusting to ${Math.round(gust)}` : ''}.`)
  else sentences.push(`A strong ${direction}erly wind of ${Math.round(windNow)} ${units.wind}${gust > windNow * 1.2 ? `, with gusts to ${Math.round(gust)}` : ''}.`)
  const total = hours.reduce((sum, i) => sum + (hourly.precipitation[i] ?? 0), 0)
  if (total >= 0.2) {
    const amount = units.precipitation === 'in' ? total.toFixed(2) : total < 10 ? total.toFixed(1) : Math.round(total)
    sentences.push(`About ${amount} ${units.precipitation} of ${noun === 'snow' ? 'snow, as water,' : 'rain'} ${evening ? 'by tomorrow night' : 'before midnight'}.`)
  }
  const sunrise = daily.sunrise[today + (evening || now > daily.sunset[today] ? 1 : 0)]
  const sunset = daily.sunset[today]
  sentences.push(
    now < sunset && !evening
      ? `The sun sets at ${clockText(sunset, offset, twelve)}.`
      : `The sun rises at ${clockText(sunrise, offset, twelve)}.`,
  )

  // The week ahead, and its best and wettest days in a sentence.
  const week = []
  for (let d = today + 1; d < Math.min(daily.high.length, today + 7); d++) week.push(d)
  const dayName = (d: number) => WEEKDAYS[placeClock(daily.start + d * 86400000 + 43200000, offset).getUTCDay()]
  const skyScore = (code: number) => ({ clear: 3, partly: 2, cloudy: 1, fog: 0.5 }[kindOf(code)] ?? 0)
  const later = week.slice(1)
  let ahead = ''
  if (later.length >= 3) {
    const best = later.reduce((a, b) => (skyScore(daily.code[b]) * 10 + celsius(daily.high[b], f) - (daily.precipitation[b] ?? 0) > skyScore(daily.code[a]) * 10 + celsius(daily.high[a], f) - (daily.precipitation[a] ?? 0) ? b : a))
    const wettest = later.reduce((a, b) => ((daily.precipitation[b] ?? 0) > (daily.precipitation[a] ?? 0) ? b : a))
    ahead = `${dayName(best)} looks the pick of the week, ${wordsFor(daily.code[best]).toLowerCase()} at ${degrees(daily.high[best])}.`
    if ((daily.precipitation[wettest] ?? 0) >= 1 && wettest !== best) {
      ahead += ` ${dayName(wettest)} is the wettest, with ${daily.precipitation[wettest]} ${units.precipitation}.`
    } else if (later.every((d) => (daily.precipitation[d] ?? 0) < 1)) {
      ahead += ' The rest of the week stays mostly dry.'
    }
  }
  const weekHigh = Math.max(...week.map((d) => daily.high[d]))
  const weekLow = Math.min(...week.map((d) => daily.low[d]))
  const span = Math.max(1, weekHigh - weekLow)

  const portrait = H > W
  // The smallest words (the labels, in capitals) 12 px at least on a panel
  // too small for the week (a watch, a 2.8" screen), 10 where the week needs
  // the room; the body 13 and 11.
  const noWeek = (!portrait && W < 380) || (portrait && H < 420)
  const smallSize = Math.max(noWeek ? 12 : 10, Math.round(Math.min(H * 0.028, W * 0.022)))
  const pad = Math.round(Math.min(W, H) * 0.05)
  const date = `${WEEKDAYS[local.getUTCDay()]}, ${local.getUTCDate()} ${MONTHS[local.getUTCMonth()]}`
  const shortDate = `${WEEKDAYS[local.getUTCDay()].substring(0, 3)} ${local.getUTCDate()} ${MONTHS[local.getUTCMonth()].substring(0, 3)}`
  const label = `font-[PT_Sans] font-bold uppercase text-[${smallSize}px] text-[${SOFT}]`
  const inner = W - pad * 2

  // The figures at the foot: all six where there is room (in a row, or two
  // rows of three on a tall panel), else the four the story does not already
  // tell (it has the wind and the sun).
  const allFigures = [
    ['Now', degrees(current.temperature)],
    ['High', degrees(daily.high[today])],
    ['Low', degrees(daily.low[today])],
    ['Rain', `${daily.precipitation[today] ?? 0} ${units.precipitation}`],
    ['Wind', `${compass(current.windDirection ?? 0)} ${Math.round(windNow)} ${units.wind}`],
    ['Daylight', `${clockText(daily.sunrise[today], offset, twelve)}–${clockText(sunset, offset, twelve)}`],
  ]
  const valueSize = Math.round(smallSize * 1.3)
  const figureWidth = ([name, value]: string[]) => Math.max(name.length * smallSize * 0.72, value.length * valueSize * 0.56)
  const allFit = portrait
    ? Math.max(...allFigures.map(figureWidth)) <= inner * 0.33 - 4
    : allFigures.reduce((sum, figure) => sum + figureWidth(figure), 0) + 5 * smallSize * 1.2 <= inner
  const figures = allFit ? allFigures : allFigures.slice(0, 4)
  const figureRows = portrait && figures.length > 4 ? 2 : 1

  // The header: the date beside the title where it fits, else under it,
  // shortened if it must be.
  const titleSize = Math.round(smallSize * 1.6)
  const dateWidth = (text: string) => text.length * smallSize * 0.66
  const dateLine = `${date} · ${weather.place}`
  const shortLine = `${shortDate} · ${weather.place}`
  const besideTitle = inner - titleSize * 5.6
  // Beside the title in full, or said short; else under it.
  const besideDate = [dateLine, shortLine].find((text) => dateWidth(text) <= besideTitle)
  const headerDate = besideDate || (dateWidth(dateLine) <= inner ? dateLine : shortLine)
  const stackedHeader = !besideDate

  // The headline and the paragraphs take the room the rest leaves them: the
  // header, the figures at the foot and the week, beside them on a wide
  // panel and under them on a tall one (on a small one the week is as many
  // days as fit, or left to the "looking ahead" sentence). Where the words
  // would run past it both sizes come down together, measured as the frame
  // sets them (frameos.measureText), or estimated from the letters where it
  // cannot; and where even that is not enough, the last sentences go.
  const measured = typeof frameos.measureText === 'function'
  const lineOf = (className: string, size: number) =>
    measured ? frameos.measureText(['Ag'], { className, width: W })[0] : Math.round(size * 1.5)
  const labelH = lineOf(label, smallSize)
  const valueH = lineOf(`font-[PT_Sans] font-bold text-[${Math.round(smallSize * 1.3)}px]`, smallSize * 1.3)
  const daySize = Math.round(smallSize * 1.15)
  const dayH = lineOf(`font-[PT_Sans] text-[${daySize}px]`, daySize)
  const header = (stackedHeader ? Math.round(smallSize * 1.6) + 2 + labelH : Math.max(Math.round(smallSize * 1.6), labelH)) + Math.round(pad * 0.25) + Math.round(pad * 0.5) + 6
  const footer = Math.round(pad * 0.4) + Math.round(pad * 0.3) + 1 + figureRows * (labelH + valueH + (figureRows > 1 ? 6 : 0))

  // The week: one line a day where the column is wide enough, else the
  // day and its figures on one line and the sky under them. Beside the story
  // it takes 30% of the width, up to 40% where that puts a day on one line
  // (twice as many days in the same height).
  const longest = Math.max(...week.map((d) => wordsFor(daily.code[d]).length))
  const oneLineNeeds = (longest + 12) * daySize * 0.52
  const wideShare = Math.max(0.3, (oneLineNeeds + pad * 0.6 + 2) / inner)
  const weekShare = portrait ? 1 : wideShare <= 0.4 ? wideShare : 0.3
  const weekColumn = portrait ? inner : Math.round(inner * weekShare - pad * 0.6 - 1)
  const oneLine = weekColumn >= oneLineNeeds
  const barH = Math.max(3, Math.round(smallSize * 0.3))
  const dayGap = Math.round(smallSize * 0.5)
  const dayRowH = dayH * (oneLine ? 1 : 2) + 3 + barH + Math.round(smallSize * 0.35) + 1
  const weekRoom = portrait ? H * 0.42 : H - pad * 2 - header - footer - labelH - Math.round(pad * 0.25)
  let days = Math.min(week.length, Math.floor((weekRoom + dayGap) / (dayRowH + dayGap)))
  if (days < 3 || noWeek) days = 0
  const shown = week.slice(0, days)
  const weekH = portrait && days ? pad + labelH + Math.round(pad * 0.25) + days * dayRowH + (days - 1) * dayGap : 0
  const textW = Math.floor(portrait || !days ? inner : inner * (1 - weekShare) - pad)

  const room = H - pad * 2 - header - footer - weekH
  const headline0 = Math.min(H * (portrait ? 0.07 : 0.1), W * (portrait ? 0.1 : 0.06)) * (headline.length > 70 ? 0.8 : headline.length > 50 ? 0.9 : 1)
  const body0 = Math.min(H * (portrait ? 0.03 : 0.042), W * (portrait ? 0.045 : 0.032))
  const headlineClass = (size: number) => `font-[Cormorant_Garamond] font-bold text-[${size}px] leading-[1.02]`
  const bodyClass = (size: number) => `font-[PT_Sans] text-[${size}px] leading-snug`
  const headlineAt = (k: number) => Math.max(17, Math.round(headline0 * k))
  const bodyAt = (k: number) => Math.max(noWeek ? 13 : 11, Math.round(body0 * k))
  const tall = (k: number, story: string, aheadText: string) => {
    const hs = headlineAt(k)
    const bs = bodyAt(k)
    const gaps = pad * 0.45 * (aheadText ? 2 : 1)
    if (measured) {
      const [a] = frameos.measureText([headline], { className: headlineClass(hs), width: textW })
      const [b, c] = frameos.measureText(aheadText ? [story, aheadText] : [story], { className: bodyClass(bs), width: textW })
      return a + b + (c || 0) + gaps
    }
    const lines = (chars: number, size: number, em: number) => Math.ceil((chars * size * em * 1.05) / textW)
    return lines(headline.length, hs, 0.45) * hs * 1.02 + lines(story.length, bs, 0.5) * bs * 1.375 +
      (aheadText ? lines(aheadText.length, bs, 0.5) * bs * 1.375 : 0) + gaps
  }
  let told = sentences.length
  let withAhead = !!ahead
  let fit = 1
  for (;;) {
    const story = sentences.slice(0, told).join(' ')
    const aheadText = withAhead ? 'LOOKING AHEAD ' + ahead : ''
    fit = 1
    while (fit > 0.6 && tall(fit, story, aheadText) > room) fit -= 0.04
    if (tall(fit, story, aheadText) <= room) break
    if (withAhead) withAhead = false
    else if (told > 2) told--
    else break
  }
  const story = sentences.slice(0, told).join(' ')
  const headlineSize = headlineAt(fit)
  const bodySize = bodyAt(fit)

  // A round panel shows only the circle inside its square: the front page
  // as one centred column, each part as wide as the circle is where it sits,
  // today's figures in the arc at the bottom, the week left for a wider screen.
  if (context.round === true) {
    const d = Math.min(W, H)
    const chord = (fromTop: number) => Math.round(2 * Math.sqrt(Math.max(0, (d / 2) ** 2 - (d / 2 - fromTop) ** 2)) - 24)
    const size = Math.max(14, Math.round(d * 0.036))
    const big = Math.round(d * 0.07 * (headline.length > 70 ? 0.8 : headline.length > 50 ? 0.9 : 1))
    const roundLabel = `font-[PT_Sans] font-bold uppercase text-[${Math.max(13, Math.round(d * 0.027))}px] text-[${SOFT}]`
    return (
      <div className={`flex flex-col items-center justify-center w-full h-full bg-[${PAPER}] text-[${INK}] text-center`}>
        <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.round(d * 0.06)}px] leading-none`}>The Weather</div>
        <div className={`${roundLabel} mt-[4px] w-[${chord(d * 0.15)}px] truncate`}>{`${date} · ${weather.place}`}</div>
        <div className={`mt-[6px] h-[2px] w-[${chord(d * 0.18)}px] bg-[${INK}]`} />
        <div className={`mt-[${Math.round(d * 0.02)}px] w-[${chord(d * 0.26)}px] font-[Cormorant_Garamond] font-bold text-[${big}px] leading-[1.02] line-clamp-3`}>{headline}</div>
        <div className={`mt-[${Math.round(d * 0.018)}px] w-[${chord(d * 0.36) - Math.round(d * 0.04)}px] font-[PT_Sans] text-[${size}px] leading-snug line-clamp-6`}>
          {sentences.join(' ')}
        </div>
        <div className={`mt-[${Math.round(d * 0.025)}px] h-[1px] w-[${chord(d * 0.8)}px] bg-[${INK}]`} />
        <div className={`flex justify-center gap-[${Math.round(d * 0.045)}px] mt-[${Math.round(d * 0.012)}px]`}>
          {figures.slice(0, 3).map(([name, value]) => (
            <div className="flex flex-col items-center">
              <div className={roundLabel}>{name}</div>
              <div className={`font-[PT_Sans] font-bold text-[${Math.round(size * 1.25)}px] ${name === 'Now' ? `text-[${ACCENT}]` : ''}`}>{value}</div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  const weekList = (
    <div className={`flex flex-col ${portrait ? 'flex-1 min-h-0 overflow-hidden' : `w-[${(weekShare * 100).toFixed(1)}%] border-l ${theme.columnRule} pl-[${Math.round(pad * 0.6)}px]`}`}>
      <div className={label}>The week ahead</div>
      <div className={`flex flex-col mt-[${Math.round(pad * 0.25)}px] gap-[${dayGap}px]`}>
        {shown.map((d) => {
          const day = placeClock(daily.start + d * 86400000 + 43200000, offset)
          const left = ((daily.low[d] - weekLow) / span) * 100
          const width = Math.max(4, ((daily.high[d] - daily.low[d]) / span) * 100)
          const name = <span className={`font-bold ${oneLine ? `w-[${Math.round(smallSize * 3.2)}px]` : 'flex-1'}`}>{WEEKDAYS[day.getUTCDay()].substring(0, 3)}</span>
          const sky = wordsFor(daily.code[d])
          const temps = [
            <span className="font-bold ml-[6px]">{degrees(daily.high[d])}</span>,
            <span className={`text-[${SOFT}] ml-[6px]`}>{degrees(daily.low[d])}</span>,
          ]
          return (
            <div className={`flex flex-col ${theme.rowRule} pb-[${Math.round(smallSize * 0.35)}px]`}>
              <div className={`flex items-baseline font-[PT_Sans] text-[${daySize}px]`}>
                {name}
                {oneLine ? <span className="flex-1 truncate">{sky}</span> : null}
                {temps}
              </div>
              {oneLine ? null : <div className={`font-[PT_Sans] text-[${daySize}px]`}>{sky}</div>}
              <div className={`relative h-[${barH}px] mt-[3px] ${theme.track}`}>
                {theme.name === 'color' ? null : <div className={`absolute left-0 right-0 top-[${Math.floor((barH - 1) / 2)}px] h-[1px] bg-[${INK}]`} />}
                <div className={`absolute top-0 bottom-0 left-[${left.toFixed(1)}%] w-[${width.toFixed(1)}%] bg-[${theme.range(celsius((daily.high[d] + daily.low[d]) / 2, f))}]`} />
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )

  return (
    <div className={`flex flex-col w-full h-full bg-[${PAPER}] text-[${INK}] p-[${pad}px]`}>
      {stackedHeader ? (
        <div className="flex flex-col">
          <div className={`font-[Cormorant_Garamond] font-bold text-[${titleSize}px] leading-none`}>The Weather</div>
          <div className={`${label} truncate mt-[2px]`}>{headerDate}</div>
        </div>
      ) : (
        <div className="flex items-end justify-between">
          <div className={`font-[Cormorant_Garamond] font-bold text-[${titleSize}px] leading-none`}>The Weather</div>
          <div className={`${label} truncate`}>{headerDate}</div>
        </div>
      )}
      <div className={`mt-[${Math.round(pad * 0.25)}px] h-[3px] bg-[${INK}]`} />
      <div className={`mt-[2px] h-[1px] bg-[${INK}]`} />
      <div className={`flex ${portrait ? 'flex-col' : 'flex-row'} flex-1 min-h-0 mt-[${Math.round(pad * 0.5)}px] gap-[${pad}px]`}>
        <div className={`flex flex-col min-w-0 ${portrait ? '' : 'flex-1 min-h-0 overflow-hidden'}`}>
          <div className={headlineClass(headlineSize)}>{headline}</div>
          <div className={`mt-[${Math.round(pad * 0.45)}px] ${bodyClass(bodySize)} text-[${INK}]`}>
            {story}
          </div>
          {ahead && withAhead ? (
            <div className={`mt-[${Math.round(pad * 0.45)}px] ${bodyClass(bodySize)}`}>
              <span className={`font-bold uppercase text-[${ACCENT}]`}>Looking ahead </span>
              {ahead}
            </div>
          ) : null}
        </div>
        {days ? weekList : null}
      </div>
      <div className={`h-[1px] bg-[${INK}] mt-[${Math.round(pad * 0.4)}px]`} />
      <div className={`flex ${figureRows > 1 ? 'flex-wrap' : ''} justify-between mt-[${Math.round(pad * 0.3)}px]`}>
        {figures.map(([name, value]) => (
          <div className={`flex flex-col ${figureRows > 1 ? 'w-[33%] mb-[6px]' : ''}`}>
            <div className={label}>{name}</div>
            <div className={`font-[PT_Sans] font-bold text-[${Math.round(smallSize * 1.3)}px] ${name === 'Now' ? `text-[${ACCENT}]` : ''}`}>{value}</div>
          </div>
        ))}
      </div>
    </div>
  )
}

